String str(def v) {
  if (v == null) { return null; }
  String s = v.toString();
  return s.isEmpty() ? null : s;
}
String cap(def v, int n) {
  String s = str(v);
  if (s == null) { return null; }
  return s.length() > n ? s.substring(0, n) : s;
}
def num(def v) {
  if (v == null) { return null; }
  if (v instanceof Number) { return ((Number) v).doubleValue(); }
  try { return Double.parseDouble(v.toString().trim()); } catch (Exception e) { return null; }
}
String hostOf(def t) {
  if (t == null) { return null; }
  String s = t.toString().trim();
  int p = s.indexOf('://');
  if (p >= 0) { s = s.substring(p + 3); }
  int sl = s.indexOf('/');
  if (sl >= 0) { s = s.substring(0, sl); }
  int at = s.lastIndexOf('@');
  if (at >= 0) { s = s.substring(at + 1); }
  if (s.startsWith('[')) {
    int e = s.indexOf(']');
    if (e > 0) { return s.substring(1, e); }
  }
  int c = s.indexOf(':');
  if (c >= 0 && s.indexOf(':', c + 1) < 0) { s = s.substring(0, c); }
  return s.isEmpty() ? null : s;
}
boolean isIp(String h) {
  if (h == null || h.isEmpty()) { return false; }
  if (h.indexOf(':') >= 0) {
    for (int i = 0; i < h.length(); i++) {
      if ('0123456789abcdefABCDEF:.'.indexOf(h.substring(i, i + 1)) < 0) { return false; }
    }
    return true;
  }
  String[] parts = h.splitOnToken('.');
  if (parts.length != 4) { return false; }
  for (String q : parts) {
    if (q.isEmpty() || q.length() > 3) { return false; }
    for (int i = 0; i < q.length(); i++) {
      if ('0123456789'.indexOf(q.substring(i, i + 1)) < 0) { return false; }
    }
    if (Integer.parseInt(q) > 255) { return false; }
  }
  return true;
}
void putv(Map m, String k, def v) { if (v != null) { m.put(k, v); } }

Map props = ctx['properties'] instanceof Map ? (Map) ctx['properties'] : new HashMap();
Map err = props['errow'] instanceof Map ? (Map) props['errow'] : new HashMap();
String text = null;
if (ctx['message'] instanceof Map) { text = str(((Map) ctx['message'])['text']); }
else if (ctx['message'] instanceof String) { text = str(ctx['message']); }
String title = null;
if (text != null) {
  int nl = text.indexOf(params['nl']);
  title = (nl >= 0 ? text.substring(0, nl) : text).trim();
}
String ruleId = str(ctx['ruleId']);

String sev = null;
if (err['severity'] != null) {
  String s = err['severity'].toString().trim().toLowerCase();
  if (s == 'informational' || s == 'information' || s == 'none') { s = 'info'; }
  else if (s == 'moderate' || s == 'med') { s = 'medium'; }
  if (s == 'critical' || s == 'high' || s == 'medium' || s == 'low' || s == 'info') { sev = s; }
}
if (sev == null) {
  String lv = ctx['level'] == null ? 'warning' : ctx['level'].toString().trim().toLowerCase();
  sev = lv == 'error' ? 'high' : (lv == 'note' ? 'low' : (lv == 'none' ? 'info' : 'medium'));
}
int lvl = sev == 'critical' ? 14 : (sev == 'high' ? 11 : (sev == 'medium' ? 8 : (sev == 'low' ? 5 : 2)));

String cwe = str(ctx['cwe']);
if (cwe == null) { cwe = str(err['cwe']); }
String target = str(err['target']);
String endpoint = str(err['endpoint']);
String method = str(err['method']);
String host = hostOf(target);

String loc = null;
if (ctx['locations'] instanceof List) {
  for (def l : ctx['locations']) {
    if (loc == null && props['synthetic_location'] != true && l instanceof Map && l['physicalLocation'] instanceof Map) {
      Map pl = (Map) l['physicalLocation'];
      if (pl['artifactLocation'] instanceof Map && ((Map) pl['artifactLocation'])['uri'] != null) {
        loc = str(((Map) pl['artifactLocation'])['uri']);
        if (loc != null && pl['region'] instanceof Map && ((Map) pl['region'])['startLine'] != null) {
          loc = loc + ':' + ((Map) pl['region'])['startLine'].toString();
        }
      }
    }
  }
  if (loc == null) {
    for (def l : ctx['locations']) {
      if (loc == null && l instanceof Map && l['logicalLocations'] instanceof List) {
        for (def ll : l['logicalLocations']) {
          if (loc == null && ll instanceof Map) { loc = str(ll['fullyQualifiedName']); }
        }
      }
    }
  }
}
if (endpoint != null && (loc == null || props['synthetic_location'] == true)) { loc = endpoint; }
if (loc == null) { loc = target; }

def cvss = num(err['cvss']);
if (cvss == null) { cvss = num(props['security-severity']); }
def cve = err['cve'];
if (cve instanceof String && ((String) cve).isEmpty()) { cve = null; }
String fp = ctx['partialFingerprints'] instanceof Map ? str(((Map) ctx['partialFingerprints'])['primaryLocationLineHash']) : null;
String id = str(ctx['doc_id']);
if (id == null && str(ctx['tmp_fp']) != null) {
  String fpTxt = str(ctx['tmp_fp']);
  byte[] fpRaw = Base64.getDecoder().decode(fpTxt.substring(fpTxt.indexOf(':') + 1));
  String fpDigits = '0123456789abcdef';
  StringBuilder fpHex = new StringBuilder();
  for (int fpJ = 0; fpJ < fpRaw.length; fpJ++) {
    int fpV = (int) fpRaw[fpJ];
    if (fpV < 0) { fpV += 256; }
    fpHex.append(fpDigits.substring(fpV / 16, fpV / 16 + 1));
    fpHex.append(fpDigits.substring(fpV % 16, fpV % 16 + 1));
  }
  id = fpHex.toString();
}

String full = 'errow ' + sev.toUpperCase() + ' ' + (cwe != null ? cwe : (ruleId != null ? ruleId : 'finding'));
if (title != null) { full = full + ': ' + title; }
if (target != null) { full = full + ' | target=' + target; }
if (endpoint != null) { full = full + ' endpoint=' + (method != null ? method + ' ' : '') + endpoint; }
if (str(err['id']) != null) { full = full + ' | finding=' + str(err['id']); }
if (cvss != null) { full = full + ' cvss=' + cvss; }
if (str(err['confidence']) != null) { full = full + ' confidence=' + str(err['confidence']); }
full = cap(full, 1000);

List groups = new ArrayList();
groups.add('errow');
groups.add('sarif');
if (cwe != null) { groups.add(cwe); }

Map alert = new HashMap();
alert['@timestamp'] = ctx['@timestamp'];
putv(alert, 'id', id);
Map src = new HashMap();
src['system'] = 'errow';
src['stream'] = 'errow.findings';
alert['source'] = src;
Map rl = new HashMap();
putv(rl, 'id', ruleId);
rl['level'] = lvl;
putv(rl, 'description', cap(text, 8000));
rl['groups'] = groups;
Map mitre = ctx['mitre'] instanceof Map ? (Map) ctx['mitre'] : null;
if (mitre != null) {
  rl['mitre'] = new HashMap(mitre);
  alert['mitre'] = new HashMap(mitre);
}
alert['rule'] = rl;
Map ag = new HashMap();
putv(ag, 'name', host != null ? host : cap(target, 256));
if (isIp(host)) { ag['ip'] = host; }
if (!ag.isEmpty()) { alert['agent'] = ag; }
putv(alert, 'location', cap(loc, 1024));
putv(alert, 'full_log', full);
alert['severity'] = sev;
Map er = new HashMap();
putv(er, 'run', str(ctx['run']));
putv(er, 'finding_id', str(err['id']));
putv(er, 'cwe', cwe);
putv(er, 'cve', cve);
putv(er, 'owasp', str(ctx['owasp']));
putv(er, 'cvss', cvss);
putv(er, 'confidence', str(err['confidence']));
putv(er, 'target', target);
putv(er, 'endpoint', endpoint);
putv(er, 'sarif_rule_id', ruleId);
putv(er, 'fingerprint', fp);
alert['errow'] = er;

def keepError = ctx['ingest_error'];
for (def k : new ArrayList(ctx.keySet())) {
  if (!k.startsWith('_')) { ctx.remove(k); }
}
ctx.putAll(alert);
if (keepError != null) { ctx['ingest_error'] = keepError; }
if (id != null) { ctx['_id'] = id; }

if (ctx['source'] instanceof String) {
  ctx['source_raw'] = ctx['source'];
  Map s = new HashMap();
  s['system'] = 'errow';
  s['stream'] = 'errow.findings';
  ctx['source'] = s;
}
if (ctx['id'] == null && ctx['doc_id'] != null) { ctx['id'] = ctx['doc_id']; }
